import json
from pathlib import Path

import numpy as np
import pandas as pd
from scipy import stats

PREPARED = Path('/Users/admin/Documents/DiscoveryRSI/closed_loop/data/prepared')
COUNTS = PREPARED / "E-MTAB-8316.counts.tsv.gz"
DESIGN = PREPARED / "E-MTAB-8316.design.json"
RESULTS = Path('/Users/admin/Documents/DiscoveryRSI/closed_loop/data/prepared/results_llm.json')

MEAN_ABS_LOG2FC_THRESHOLD = PARAMS["magnitude_threshold"]
SIGN_CONSISTENCY_MIN = PARAMS["sign_consistency_min"]
TREAT = PARAMS["condition_treatment"]
CTRL = PARAMS["condition_control"]
GROUP_COLS = PARAMS["pair_group_cols"]
ALPHA = 0.05
ROBUST_KEEP_FRACTION = 0.5


def main():
    counts = pd.read_csv(COUNTS, sep="\t", compression="gzip")
    design = json.loads(DESIGN.read_text(encoding="utf-8"))
    d = pd.DataFrame(design)

    lib = counts.iloc[:, 1:].sum(axis=0)
    cpm = np.log2(counts.iloc[:, 1:].mul(1e6).div(lib, axis=1) + 1.0)

    pair_map = {}
    for key, grp in d.groupby(GROUP_COLS):
        t = grp[grp["condition"] == TREAT]["sample_id"].tolist()
        c = grp[grp["condition"] == CTRL]["sample_id"].tolist()
        if t and c:
            ks = "_".join(str(x) for x in key) if isinstance(key, tuple) else str(key)
            pair_map[ks] = (t[0], c[0])
    if not pair_map:
        raise SystemExit("no donor pairs with both conditions")

    lfc = pd.DataFrame(
        {key: (cpm[t_id] - cpm[c_id]).values for key, (t_id, c_id) in pair_map.items()},
        index=counts["feature"],
    )
    mean_lfc = lfc.mean(axis=1)
    n_pairs = len(pair_map)
    sign_consistency = (np.sign(lfc.values) == np.sign(mean_lfc.values)[:, None]).sum(axis=1) / n_pairs
    mean_all = cpm.mean(axis=1)
    high_expr = mean_all > mean_all.median()

    criteria = {
        "mean_abs_log2fc_threshold": MEAN_ABS_LOG2FC_THRESHOLD,
        "sign_consistency": f"{SIGN_CONSISTENCY_MIN:.4f}",
        "sign_consistency_observed": float(sign_consistency.max()),
        "n_pairs": n_pairs,
        "feature_overlap": PARAMS["overlap_note"],
    }
    mask = (
        (mean_lfc.abs() >= MEAN_ABS_LOG2FC_THRESHOLD)
        & (sign_consistency >= SIGN_CONSISTENCY_MIN)
        & high_expr
    )
    program_genes = mean_lfc[mask].index.tolist()

    if not program_genes:
        near = mean_lfc[mean_lfc.abs() >= MEAN_ABS_LOG2FC_THRESHOLD].index.tolist()
        results = {
            "program": {
                "criteria": criteria, "genes": [], "n_genes": 0,
                "near_threshold_genes": near, "near_threshold_n": len(near),
            },
            "baseline": {
                "context_contrast": None, "p_value": None, "ci_lower": None, "ci_upper": None,
                "donor_level": {},
                "method": "donor-aware pseudobulk paired test on program composite score",
                "note": "Prespecified intervention-associated program is empty; no context contrast computed.",
            },
            "ridge": {
                "context_coefficient": None, "composition_robust": False,
                "covariates": PARAMS["covariates"],
                "note": "No program to regress.",
            },
            "outcome": "adverse",
            "justification": (
                f"Prespecified program empty (|mean log2FC|>={MEAN_ABS_LOG2FC_THRESHOLD}, "
                f"sign>={SIGN_CONSISTENCY_MIN}; {len(near)} genes pass magnitude but fail "
                "directional consistency). Context contrast not supported by available data. "
                "Exploratory donor-aware diagnostic; does not establish direct target causality."
            ),
            "limitations": (
                "Exploratory donor-aware diagnostic, n={len(pair_map)*2} samples "
                f"({len(pair_map)} donor pairs). Overlap: {PARAMS['overlap_note']}. "
                "Does not establish direct target causality, clinical efficacy, or mechanism."
            ),
        }
    else:
        don = pd.concat(
            [
                pd.DataFrame({
                    "sample_id": [t_id, c_id], "condition": [TREAT, CTRL], "pair": key,
                    "program_score": [
                        float(cpm.loc[program_genes, t_id].mean()),
                        float(cpm.loc[program_genes, c_id].mean()),
                    ],
                })
                for key, (t_id, c_id) in pair_map.items()
            ],
            ignore_index=True,
        )
        don = don.merge(d[["sample_id", "donor_id"]], on="sample_id")
        cont = don.pivot(index="pair", columns="condition", values="program_score")
        delta = cont[TREAT] - cont[CTRL]
        t_stat, p_value = stats.ttest_rel(cont[TREAT], cont[CTRL])
        donor_level = {str(k): float(v) for k, v in delta.to_dict().items()}
        context_contrast = float(delta.mean())

        from sklearn.linear_model import Ridge

        X = pd.DataFrame(
            {
                "intercept": 1.0,
                "condition_unc": (don["condition"] == TREAT).astype(float),
                **{f"donor_{k}": (don["donor_id"] == k).astype(float)
                    for k in sorted(don["donor_id"].unique())[1:]},
            },
            index=don.index,
        )
        libsize = don["sample_id"].map(lib).astype(float)
        composition = (libsize - libsize.mean()) / libsize.std()
        X_ridge = X.copy()
        X_ridge["composition"] = composition.values
        ridge = Ridge(alpha=1.0).fit(X_ridge, don["program_score"])
        coeff_full = float(ridge.coef_[X_ridge.columns.get_loc("condition_unc")])
        ridge_nc = Ridge(alpha=1.0).fit(X.drop(columns=["composition"]), don["program_score"])
        coeff_base = float(ridge_nc.coef_[X.drop(columns=["composition"]).columns.get_loc("condition_unc")])
        robust = abs(coeff_full) >= ROBUST_KEEP_FRACTION * abs(coeff_base)
        baseline_supported = (np.sign(context_contrast) == np.sign(coeff_full)) and (p_value < ALPHA)
        outcome = "supportive" if (baseline_supported and robust) else ("inconclusive" if baseline_supported else "adverse")

        results = {
            "program": {"criteria": criteria, "genes": program_genes, "n_genes": len(program_genes)},
            "baseline": {
                "context_contrast": context_contrast, "p_value": float(p_value),
                "ci_lower": float(delta.mean() - 1.96 * delta.std(ddof=1) / np.sqrt(len(delta))),
                "ci_upper": float(delta.mean() + 1.96 * delta.std(ddof=1) / np.sqrt(len(delta))),
                "donor_level": donor_level,
                "method": "donor-aware pseudobulk paired test on program composite score",
            },
            "ridge": {
                "context_coefficient": coeff_full, "composition_robust": bool(robust),
                "covariates": PARAMS["covariates"],
            },
            "outcome": outcome,
            "justification": (
                f"Program {len(program_genes)} genes; baseline contrast {context_contrast:.3f} "
                f"(p={p_value:.3g}); ridge coeff {coeff_full:.3f}, composition-robust={robust}. "
                "Exploratory donor-aware diagnostic; does not establish direct target causality."
            ),
            "limitations": (
                "Exploratory donor-aware diagnostic; overlap: {PARAMS['overlap_note']}. "
                "Does not establish direct target causality, clinical efficacy, or mechanism."
            ),
        }

    RESULTS.parent.mkdir(parents=True, exist_ok=True)
    RESULTS.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")
    print("wrote", RESULTS)


if __name__ == "__main__":
    main()
